INSERT OR IGNORE INTO plugin_gtm_scheduled_sends (id, lead_id, chat_id, bubbles, content_hash, send_at, status, claim_token, claimed_at, sent_at, error, created_at, updated_at) SELECT id, lead_id, chat_id, bubbles, content_hash, send_at, status, claim_token, claimed_at, sent_at, error, created_at, updated_at FROM scheduled_sends;
DROP TABLE scheduled_sends;
CREATE TABLE IF NOT EXISTS gtm_sends (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL, chat_id TEXT, bubble TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'sent', error TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS plugin_gtm_sends (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL, chat_id TEXT, bubble TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'sent', error TEXT, created_at INTEGER NOT NULL);
INSERT OR IGNORE INTO plugin_gtm_sends (id, lead_id, chat_id, bubble, status, error, created_at) SELECT id, lead_id, chat_id, bubble, status, error, created_at FROM gtm_sends;
DROP TABLE gtm_sends;
CREATE TABLE IF NOT EXISTS wa_outreach_class (msg_id TEXT PRIMARY KEY, chat_id TEXT, is_outreach INTEGER NOT NULL, reason TEXT, classified_at INTEGER);
CREATE TABLE IF NOT EXISTS plugin_gtm_wa_outreach_class (msg_id TEXT PRIMARY KEY, chat_id TEXT, is_outreach INTEGER NOT NULL, reason TEXT, classified_at INTEGER);
INSERT OR IGNORE INTO plugin_gtm_wa_outreach_class (msg_id, chat_id, is_outreach, reason, classified_at) SELECT msg_id, chat_id, is_outreach, reason, classified_at FROM wa_outreach_class;
